func multiply(num1 string, num2 string) string {
	if num1 == "0" || num2 == "0" {
		return "0"
	}
	m, n := len(num1), len(num2)
	res := make([]int, m+n)
	for i := m - 1; i >= 0; i-- {
		for j := n - 1; j >= 0; j-- {
			mul := int(num1[i]-'0') * int(num2[j]-'0')
			p2 := i + j + 1
			sum := mul + res[p2]
			res[p2] = sum % 10
			res[i+j] += sum / 10
		}
	}
	var sb strings.Builder
	for _, d := range res {
		if sb.Len() == 0 && d == 0 {
			continue
		}
		sb.WriteByte(byte(d) + '0')
	}
	if sb.Len() == 0 {
		return "0"
	}
	return sb.String()
}

class Solution {
  public String multiply(String num1, String num2) {
    if (num1.equals("0") || num2.equals("0")) {
      return "0";
    }
    int m = num1.length(), n = num2.length();
    int[] ansArr = new int[m + n];
    for (int i = m - 1; i >= 0; i--) {
      int x = num1.charAt(i) - '0';
      for (int j = n - 1; j >= 0; j--) {
        int y = num2.charAt(j) - '0';
        ansArr[i + j + 1] += x * y;
      }
    }
    for (int i = m + n - 1; i > 0; i--) {
      ansArr[i - 1] += ansArr[i] / 10;
      ansArr[i] %= 10;
    }
    int index = ansArr[0] == 0 ? 1 : 0;
    StringBuffer ans = new StringBuffer();
    while (index < m + n) {
      ans.append(ansArr[index]);
      index++;
    }
    return ans.toString();
  }
}

class Solution:
    def multiply(self, num1: str, num2: str) -> str:
        if num1 == "0" or num2 == "0":
            return "0"
        m, n = len(num1), len(num2)
        res = [0] * (m + n)
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                mul = int(num1[i]) * int(num2[j])
                p2 = i + j + 1
                total = mul + res[p2]
                res[p2] = total % 10
                res[i + j] += total // 10
        out = "".join(str(d) for d in res).lstrip("0")
        return out or "0"

impl Solution {
  pub fn multiply(num1: String, num2: String) -> String {
    if num1 == "0" || num2 == "0" {
      return "0".to_string();
    }
    let a = num1.as_bytes();
    let b = num2.as_bytes();
    let (m, n) = (a.len(), b.len());
    let mut res = vec![0i32; m + n];
    for i in (0..m).rev() {
      for j in (0..n).rev() {
        let mul = (a[i] - b'0') as i32 * (b[j] - b'0') as i32;
        let p2 = i + j + 1;
        let total = mul + res[p2];
        res[p2] = total % 10;
        res[i + j] += total / 10;
      }
    }
    let out: String = res
      .iter()
      .map(|d| (d + b'0' as i32) as u8 as char)
      .collect::<String>();
    out.trim_start_matches('0').to_string()
  }
}

const multiply = (num1: string, num2: string): string => {
  if (num1 === '0' || num2 === '0') return '0';
  const m = num1.length;
  const n = num2.length;
  const res: number[] = new Array(m + n).fill(0);
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      const mul = (num1.charCodeAt(i) - 48) * (num2.charCodeAt(j) - 48);
      const p2 = i + j + 1;
      const total = mul + res[p2];
      res[p2] = total % 10;
      res[i + j] += Math.floor(total / 10);
    }
  }
  const out = res.join('').replace(/^0+/, '');
  return out === '' ? '0' : out;
};
